--
-- Table structure for table `predictions`
--

DROP TABLE IF EXISTS `predictions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `predictions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `program_id` int(11) NOT NULL,
  `academic_year` varchar(20) NOT NULL,
  `semester` int(11) NOT NULL,
  `predicted_total` int(11) NOT NULL,
  `predicted_male` int(11) DEFAULT NULL,
  `predicted_female` int(11) DEFAULT NULL,
  `confidence` decimal(5,4) DEFAULT NULL,
  `model_ensemble` varchar(255) DEFAULT 'SARMAX+Prophet+LSTM',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `model_name` varchar(50) NOT NULL DEFAULT 'Ensemble',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_program_pred_sem_model` (`program_id`,`academic_year`,`semester`,`model_name`),
  KEY `idx_program_year` (`program_id`,`academic_year`),
  KEY `idx_model_ensemble` (`model_ensemble`),
  CONSTRAINT `predictions_ibfk_1` FOREIGN KEY (`program_id`) REFERENCES `casprograms` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

